import{_ as n,a0 as p,w as s,s as d,I as o,x as t,a1 as r,A as i,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"在CentOS上配置基于主机的入侵检测系统（IDS） | LCTT x X-CMD","titleTemplate":false,"description":"在CentOS上配置基于主机的入侵检测系统（IDS） | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在CentOS上配置基于主机的入侵检测系统（IDS） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在CentOS上配置基于主机的入侵检测系统（IDS） | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141008 How to configure a host intrusion detection system on CentOS","title":"在CentOS上配置基于主机的入侵检测系统（IDS）","tag":"201411","desc":""},"relativePath":"201411/20141008 How to configure a host intrusion detection system on CentOS.md","filePath":"[post].md"}'),c={name:"201411/20141008 How to configure a host intrusion detection system on CentOS.md"};function m(h,e,f,u,A,I){const a=p("Link");return s(),d("div",null,[e[15]||(e[15]=o("h1",{id:"在centos上配置基于主机的入侵检测系统-ids",tabindex:"-1"},[t("在CentOS上配置基于主机的入侵检测系统（IDS） "),o("a",{class:"header-anchor",href:"#在centos上配置基于主机的入侵检测系统-ids","aria-label":"Permalink to “在CentOS上配置基于主机的入侵检测系统（IDS）”"},"​")],-1)),e[16]||(e[16]=o("p",null,"所有系统管理员想要在他们生产服务器上首先要部署的安全手段之一，就是检测文件篡改的机制——不仅仅是文件内容，而且也包括它们的属性。",-1)),o("p",null,[r(a,{href:"http://aide.sourceforge.net/"},{default:i(()=>[...e[0]||(e[0]=[t("AIDE",-1)])]),_:1}),e[1]||(e[1]=t(" （“高级入侵检测环境”的简称）是一个开源的基于主机的入侵检测系统。AIDE通过检查大量文件属性的不一致性来检查系统二进制文件和基本配置文件的完整性，这些文件属性包括权限、文件类型、索引节点、链接数、链接名、用户、组、文件大小、块计数、修改时间、添加时间、创建时间、acl、SELinux安全上下文、xattrs，以及md5/sha校验值在内的各种特征。",-1))]),e[17]||(e[17]=l(`<p>AIDE通过扫描一台（未被篡改）的Linux服务器的文件系统来构建文件属性数据库，以后将服务器文件属性与数据库中的进行校对，然后在服务器运行时对被修改的索引了的文件发出警告。出于这个原因，AIDE必须在系统更新后或其配置文件进行合法修改后重新对受保护的文件做索引。</p><p>对于某些客户，他们可能会根据他们的安全策略在他们的服务器上强制安装某种入侵检测系统。但是，不管客户是否要求，系统管理员都应该部署一个入侵检测系统，这通常是一个很好的做法。</p><h3 id="在-centos或rhel-上安装aide" tabindex="-1">在 CentOS或RHEL 上安装AIDE <a class="header-anchor" href="#在-centos或rhel-上安装aide" aria-label="Permalink to “在 CentOS或RHEL 上安装AIDE”">​</a></h3><p>AIDE的初始安装（同时是首次运行）最好是在系统刚安装完后，并且没有任何服务暴露在互联网甚至局域网时。在这个早期阶段，我们可以将来自外部的一切闯入和破坏风险降到最低限度。事实上，这也是确保系统在AIDE构建其初始数据库时保持干净的唯一途径。（LCTT 译注：当然，如果你的安装源本身就存在安全隐患，则无法建立可信的数据记录）</p><p>出于上面的原因，在安装完系统后，我们可以执行下面的命令安装AIDE：</p><pre><code> # yum install aide 
</code></pre><p>我们需要将我们的机器从网络断开，并实施下面所述的一些基本配置任务。</p><h3 id="配置aide" tabindex="-1">配置AIDE <a class="header-anchor" href="#配置aide" aria-label="Permalink to “配置AIDE”">​</a></h3><p>默认配置文件是/etc/aide.conf，该文件介绍了几个示例保护规则（如FIPSR，NORMAL，DIR，DATAONLY），各个规则后面跟着一个等号以及要检查的文件属性列表，或者某些预定义的规则（由+分隔）。你也可以使用此种格式自定义规则。</p><p><img src="https://farm3.staticflickr.com/2947/15446746115_7d0a291b0a_o.png" alt=""></p><pre><code>FIPSR = p+i+n+u+g+s+m+c+acl+selinux+xattrs+sha256
NORMAL = FIPSR+sha512
</code></pre><p>例如，上面的例子说明，NORMAL规则将检查下列属性的不一致性：权限（p）、索引节点（i）、链接数（n）、用户（u）、组（g）、大小（s）、修改时间（m）、创建时间（c）、ACL（acl）、SELinux（selinux）、xattrs（xattr）、SHA256/SHA512校验和（sha256和sha512）。</p><p>定义的规则可灵活地用于不同的目录和文件（用正则表达式表示）。</p><p><img src="https://farm6.staticflickr.com/5601/15259978179_f93b757c56_o.png" alt=""></p><p>条目之前的感叹号（！）告诉AIDE忽略子目录（或目录中的文件），对于这些可以另外定义规则。</p><p>在上面的例子中，PERMS是用于/etc机器子目录和文件的默认规则。然而，对于/etc中的备份文件（如/etc/.*~）则不应用任何规则，也没有规则用于/etc/mtab文件。对于/etc中的其它一些选定的子目录或文件，使用NORMAL规则替代默认规则PERMS。</p><p>定义并应用正确的规则到系统中正确的位置，是使用AIDE最难的一部分，但作一个好的判断是一个良好的开始。作为首要的一条规则，不要检查不必要的属性。例如，检查/var/log或/var/spool里头的文件的修改时间将导致大量误报，因为许多的应用程序和守护进程经常会写入内容到该位置，而这些内容都没有问题。此外，检查多个校验值可能会加强安全性，但随之而来的是AIDE的运行时间的增加。</p><p>可选的，如果你使用MAILTO变量指定电子邮件地址，就可以将检查结果发送到你的邮箱。将下面这一行放到/etc/aide.conf中的任何位置即可。</p><pre><code>MAILTO=root@localhost
</code></pre><h3 id="首次运行aide" tabindex="-1">首次运行AIDE <a class="header-anchor" href="#首次运行aide" aria-label="Permalink to “首次运行AIDE”">​</a></h3><p>运行以下命令来初始化AIDE数据库：</p><pre><code> # aide --init 
</code></pre><p><img src="https://farm3.staticflickr.com/2942/15446399402_198472e983_o.png" alt=""></p><p>根据/etc/aide.conf生成的/var/lib/aide/aide.db.new.gz文件需要被重命名为/var/lib/aide/aide.db.gz，以便AIDE能读取它：</p><pre><code> # mv /var/lib/aide/aide.db.new.gz /var/lib/aide.db.gz 
</code></pre><p>现在，是时候来将我们的系统与数据库进行第一次校对了。任务很简单，只需运行：</p><pre><code> # aide 
</code></pre><p>在没有选项时，AIDE假定使用了--check选项。</p><p>如果在数据库创建后没有对系统做过任何修改，AIDE将会以OK信息来结束本次校对。</p><p><img src="https://farm3.staticflickr.com/2948/15260041950_f568b3996a_o.png" alt=""></p><h3 id="生产环境中管理aide" tabindex="-1">生产环境中管理AIDE <a class="header-anchor" href="#生产环境中管理aide" aria-label="Permalink to “生产环境中管理AIDE”">​</a></h3><p>在构建了一个初始AIDE数据库后，作为不断进行的系统管理活动，你常常需要因为某些合法的理由更新受保护的服务器。每次服务器更新后，你必须重新构建AIDE数据库，以更新数据库内容。要完成该任务，请执行以下命令：</p><pre><code> # aide --update 
</code></pre><p>要使用AIDE保护生产系统，可能最好通过任务计划调用AIDE来周期性检查不一致性。例如，要让AIDE每天运行一次，并将结果发送到邮箱：</p><pre><code> # crontab -e 
</code></pre><hr><pre><code>0 0 * * * /usr/sbin/aide --check | /usr/bin/mail -s &quot;AIDE run for $HOSTNAME&quot; your@email.com
</code></pre><h3 id="测试aide检查文件篡改" tabindex="-1">测试AIDE检查文件篡改 <a class="header-anchor" href="#测试aide检查文件篡改" aria-label="Permalink to “测试AIDE检查文件篡改”">​</a></h3><p>下面的测试环境将演示AIDE是如何来检查文件的完整性的。</p><h4 id="测试环境-1" tabindex="-1">测试环境 1 <a class="header-anchor" href="#测试环境-1" aria-label="Permalink to “测试环境 1”">​</a></h4><p>让我们添加一个新文件（如/etc/fake）。</p><pre><code># cat /dev/null &gt; /etc/fake 
</code></pre><p><img src="https://farm3.staticflickr.com/2941/15260140358_f1d758d354_o.png" alt=""></p><h4 id="测试环境-2" tabindex="-1">测试环境 2 <a class="header-anchor" href="#测试环境-2" aria-label="Permalink to “测试环境 2”">​</a></h4><p>让我们修改文件权限，然后看看它是否被检测到。</p><pre><code> # chmod 644 /etc/aide.conf 
</code></pre><h4 id="测试环境-3" tabindex="-1">测试环境 3 <a class="header-anchor" href="#测试环境-3" aria-label="Permalink to “测试环境 3”">​</a></h4><p>最后，让我们修改文件内容（如，添加一个注释行到/etc/aide.conf）。</p><pre><code>echo &quot;#This is a comment&quot; &gt;&gt; /etc/aide.conf 
</code></pre><p><img src="https://farm4.staticflickr.com/3936/15259978229_3ff1ea950e_b.jpg" alt=""></p><p>上面的截图中，第一栏显示了文件的属性，第二栏是AIDE数据库中的值，而第三栏是更新后的值。第三栏中空白部分表示该属性没有改动（如本例中的ACL）。</p><h3 id="结尾" tabindex="-1">结尾 <a class="header-anchor" href="#结尾" aria-label="Permalink to “结尾”">​</a></h3><p>如果你曾经发现你自己有很好的理由确信系统被入侵了，但是第一眼又不能确定到底哪些东西被改动了，那么像AIDE这样一个基于主机的入侵检测系统就会很有帮助了，因为它可以帮助你很快识别出哪些东西被改动过，而不是通过猜测来浪费宝贵的时间。</p><hr>`,54)),o("p",null,[e[3]||(e[3]=t("via: ",-1)),r(a,{href:"http://xmodulo.com/host-intrusion-detection-system-centos.html"},{default:i(()=>[...e[2]||(e[2]=[t("http://xmodulo.com/host-intrusion-detection-system-centos.html",-1)])]),_:1})]),o("p",null,[e[7]||(e[7]=t("作者：",-1)),r(a,{href:"http://xmodulo.com/author/gabriel"},{default:i(()=>[...e[4]||(e[4]=[t("Gabriel Cánepa",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),r(a,{href:"https://github.com/GOLinux"},{default:i(()=>[...e[5]||(e[5]=[t("GOLinux",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),r(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[6]||(e[6]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创翻译，",-1)),r(a,{href:"http://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const x=n(c,[["render",m]]);export{b as __pageData,x as default};
